    assert response.status == 200
    assert response.body == {"customer_id": "c1", "orders": []}


def test_order_history_newest_first_with_status(shop):
    first = order(shop, "c1", ("BOOK", 1)).body["order_id"]
    order(shop, "c2", ("PEN", 1))
    second = order(shop, "c1", ("PEN", 2)).body["order_id"]
    shop.orders.handle_cancel(first)

    response = shop.insights.handle_order_history("c1")
    assert response.status == 200
    assert response.body["customer_id"] == "c1"
    assert response.body["orders"] == [
        {"order_id": second, "status": "placed", "total_cents": 600},
        {"order_id": first, "status": "cancelled", "total_cents": 2500},
    ]


def test_order_history_totals_match_order_summary_including_discount(shop):
    gold = order(shop, "c2", ("LAMP", 2)).body["order_id"]
    standard = order(shop, "c1", ("LAMP", 2)).body["order_id"]

    gold_entry = shop.insights.handle_order_history("c2").body["orders"][0]
    standard_entry = shop.insights.handle_order_history("c1").body["orders"][0]
    assert gold_entry["order_id"] == gold
    assert gold_entry["total_cents"] == shop.orders.handle_get(gold).body["total_cents"] == 10200
